=== FILE: skid_buffer.v ===
// skid_buffer: register slice for one valid/ready stream.
// Implements microarchitecture.md (two registers: output and skid).
// Every output is a flop or the inverse of one; inputs reach only next state.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer beat when two are held.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Upstream ready is the inverse of a flop.
    assign s_ready = !skid_valid;

    // Output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // Upstream transfer on this edge.
    wire s_fire = s_valid && !skid_valid;

    // Next-state signals.
    reg             m_valid_d;
    reg             m_load;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg             skid_load;

    always @* begin
        m_valid_d    = m_valid;
        m_load       = 1'b0;
        m_data_d     = s_data;
        skid_valid_d = skid_valid;
        skid_load    = 1'b0;
        if (m_free) begin
            if (skid_valid) begin
                // Skid beat moves to the output; s_ready is low, so no input beat.
                m_valid_d    = 1'b1;
                m_load       = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // Input beat (if any) goes straight to the output register.
                m_valid_d = s_valid;
                m_load    = s_valid;
                m_data_d  = s_data;
            end
        end else if (s_fire) begin
            // Output stalled: the accepted beat goes into the skid register.
            skid_valid_d = 1'b1;
            skid_load    = 1'b1;
        end
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (microarchitecture.md section 2); load enables only.
    always @(posedge clk) begin
        if (m_load) begin
            m_data <= m_data_d;
        end
        if (skid_load) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    // Design-intent properties (not submitted to the proof gate in this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) begin
            assume(!rst_n);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end else if ($past(m_valid) && !$past(m_ready)) begin
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
            if (skid_valid) begin
                assert(m_valid);
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(skid_valid && m_ready);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
