// Self-checking testbench for skid_buffer.
// Two lanes (WIDTH 8 and WIDTH 1) each run directed and random traffic
// against a reference model of up to two beats. Only the top module reads
// plusargs and calls $finish.

module skid_buffer_tb_lane #(
    parameter integer W    = 8,
    parameter integer SEED = 1
) (
    input  wire        clk,
    output reg  [31:0] passed,
    output reg  [31:0] failed,
    output reg         done
);
    localparam [W-1:0] ZERO = {W{1'b0}};

    reg          rst_n;
    reg          s_valid;
    wire         s_ready;
    reg  [W-1:0] s_data;
    wire         m_valid;
    reg          m_ready;
    wire [W-1:0] m_data;

    skid_buffer #(.WIDTH(W)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready),
        .s_data  (s_data),
        .m_valid (m_valid),
        .m_ready (m_ready),
        .m_data  (m_data)
    );

    // Reference model: queue of up to two beats, q0 oldest.
    reg [W-1:0] q0;
    reg [W-1:0] q1;
    reg [1:0]   cnt;
    reg         model_ok;
    reg         prev_stall;
    reg [W-1:0] prev_md;

    // Samples taken just before each edge.
    reg         f_s;
    reg         f_m;
    reg         p_mv;
    reg         p_mr;
    reg         p_sv;
    reg [W-1:0] p_sd;

    // Outputs recorded for the in-cycle independence check.
    reg         o_sr;
    reg         o_mv;
    reg [W-1:0] o_md;

    // Scoreboard and coverage counters.
    reg [31:0] n_in;
    reg [31:0] n_out;
    reg [31:0] n_drop;
    reg [31:0] ev_load;
    reg [31:0] ev_both;
    reg [31:0] run_both;
    reg [31:0] max_run;
    reg [31:0] ev_skid;
    reg [31:0] ev_refuse;
    reg [31:0] ev_unstall_full;
    reg [31:0] ev_hold;
    reg [31:0] ev_rst_held;
    reg [31:0] ev_wiggle;

    reg [31:0] rnd;
    reg [31:0] rnd_d;
    reg [31:0] ctr;
    integer    seed;
    integer    i;

    task chk;
        input            ok;
        input [8*28-1:0] what;
        begin
            if (ok) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("skid_buffer W=%0d: check '%0s' failed at time %0t", W, what, $time);
            end
        end
    endtask

    task check_outputs;
        begin
            chk(m_valid === (cnt != 2'd0), "m_valid matches model");
            chk(s_ready === (cnt != 2'd2), "s_ready matches model");
            if (cnt != 2'd0) begin
                chk(m_data === q0, "m_data is oldest beat");
            end
            if (prev_stall) begin
                chk((m_valid === 1'b1) && (m_data === prev_md), "stalled beat holds");
                ev_hold = ev_hold + 32'd1;
            end
        end
    endtask

    // Flip the inputs inside the cycle; registered outputs must not move.
    task wiggle;
        begin
            o_sr = s_ready;
            o_mv = m_valid;
            o_md = m_data;
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            chk((s_ready === o_sr) && (m_valid === o_mv) && (m_data === o_md),
                "outputs ignore inputs");
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            chk((s_ready === o_sr) && (m_valid === o_mv) && (m_data === o_md),
                "outputs ignore inputs back");
            ev_wiggle = ev_wiggle + 32'd1;
        end
    endtask

    task update_model;
        begin
            if (f_s && f_m) begin
                ev_both  = ev_both + 32'd1;
                run_both = run_both + 32'd1;
                if (run_both > max_run) max_run = run_both;
            end else begin
                run_both = 32'd0;
            end
            if (f_s && (cnt == 2'd0)) ev_load = ev_load + 32'd1;
            if (f_s && (cnt == 2'd1) && !p_mr) ev_skid = ev_skid + 32'd1;
            if (p_sv && (cnt == 2'd2)) ev_refuse = ev_refuse + 32'd1;
            if (f_m && (cnt == 2'd2)) ev_unstall_full = ev_unstall_full + 32'd1;
            if (f_m) begin
                if (cnt == 2'd0) begin
                    chk(1'b0, "pop from empty model");
                end else begin
                    q0    = q1;
                    cnt   = cnt - 2'd1;
                    n_out = n_out + 32'd1;
                end
            end
            if (f_s) begin
                if (cnt == 2'd2) begin
                    chk(1'b0, "push into full model");
                end else begin
                    if (cnt == 2'd0) q0 = p_sd;
                    else             q1 = p_sd;
                    cnt  = cnt + 2'd1;
                    n_in = n_in + 32'd1;
                end
            end
            prev_stall = p_mv && !p_mr;
        end
    endtask

    // One clock: drive at negedge, check, sample, then update model at posedge.
    task cycle;
        input         sv;
        input [W-1:0] sd;
        input         mr;
        input         rs;
        begin
            @(negedge clk);
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            rst_n   = rs;
            #1;
            if (model_ok) begin
                check_outputs;
                wiggle;
            end
            p_sv    = s_valid;
            p_sd    = s_data;
            p_mr    = m_ready;
            p_mv    = m_valid;
            f_s     = s_valid && s_ready;
            f_m     = m_valid && m_ready;
            prev_md = m_data;
            @(posedge clk);
            if (!rst_n) begin
                if (model_ok && (cnt != 2'd0)) begin
                    ev_rst_held = ev_rst_held + 32'd1;
                    n_drop      = n_drop + {30'd0, cnt};
                end
                cnt        = 2'd0;
                model_ok   = 1'b1;
                prev_stall = 1'b0;
                run_both   = 32'd0;
            end else if (model_ok) begin
                update_model;
            end
        end
    endtask

    initial begin
        passed = 32'd0;
        failed = 32'd0;
        done   = 1'b0;
        q0 = ZERO; q1 = ZERO; cnt = 2'd0;
        model_ok = 1'b0; prev_stall = 1'b0; prev_md = ZERO;
        f_s = 1'b0; f_m = 1'b0; p_mv = 1'b0; p_mr = 1'b0; p_sv = 1'b0; p_sd = ZERO;
        o_sr = 1'b0; o_mv = 1'b0; o_md = ZERO;
        n_in = 32'd0; n_out = 32'd0; n_drop = 32'd0;
        ev_load = 32'd0; ev_both = 32'd0; run_both = 32'd0; max_run = 32'd0;
        ev_skid = 32'd0; ev_refuse = 32'd0; ev_unstall_full = 32'd0;
        ev_hold = 32'd0; ev_rst_held = 32'd0; ev_wiggle = 32'd0;
        rnd = 32'd0; rnd_d = 32'd0; ctr = 32'd0;
        seed = SEED;
        rst_n = 1'b0; s_valid = 1'b0; m_ready = 1'b0; s_data = ZERO;

        // A. Reset, with a beat offered during reset; check reset values.
        cycle(1'b0, ZERO, 1'b0, 1'b0);
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b1, 1'b0);
        cycle(1'b0, ZERO, 1'b0, 1'b0);
        #1;
        chk(m_valid === 1'b0, "reset: m_valid low");
        chk(s_ready === 1'b1, "reset: s_ready high");

        // B. Idle.
        cycle(1'b0, ZERO, 1'b1, 1'b1);
        cycle(1'b0, ZERO, 1'b1, 1'b1);

        // C. One-cycle latency: a beat accepted on edge E is offered after E.
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b1, 1'b1);
        #1;
        chk((m_valid === 1'b1) && (m_data === ctr[W-1:0]), "latency: offered after E");
        cycle(1'b0, ZERO, 1'b1, 1'b1);
        #1;
        chk(m_valid === 1'b0, "latency: beat leaves once");

        // D. Full throughput: a long stream with m_ready high.
        for (i = 0; i < 40; i = i + 1) begin
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], 1'b1, 1'b1);
        end
        cycle(1'b0, ZERO, 1'b1, 1'b1);
        #1;
        chk(max_run >= 32'd39, "full throughput, no bubble");
        chk(m_valid === 1'b0, "throughput: drained");

        // E. Stall with one beat held (second accepted), then two (third refused).
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        #1;
        chk(s_ready === 1'b1, "stall: one held, ready");
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        #1;
        chk(s_ready === 1'b0, "stall: two held, not ready");
        for (i = 0; i < 4; i = i + 1) begin
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        end
        #1;
        chk((cnt == 2'd2) && (m_valid === 1'b1), "stall: third refused");
        // Ready high for one cycle: one beat leaves, ready rises.
        cycle(1'b1, ctr[W-1:0], 1'b1, 1'b1);
        #1;
        chk((s_ready === 1'b1) && (cnt == 2'd1), "unstall: ready rises");
        // Ready low for one cycle, then a stream.
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        for (i = 0; i < 8; i = i + 1) begin
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], 1'b1, 1'b1);
        end
        // Ready low for several cycles, then a stream.
        for (i = 0; i < 5; i = i + 1) begin
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        end
        for (i = 0; i < 8; i = i + 1) begin
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], 1'b1, 1'b1);
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b0, ZERO, 1'b1, 1'b1);
        end
        #1;
        chk((cnt == 2'd0) && (m_valid === 1'b0) && (s_ready === 1'b1), "directed: drained");

        // F. Random traffic in three phases, then a drain.
        for (i = 0; i < 1500; i = i + 1) begin
            rnd   = $random(seed);
            rnd_d = $random(seed);
            cycle(rnd[2:0] < 3'd5, rnd_d[W-1:0], rnd[5:3] < 3'd5, 1'b1);
        end
        for (i = 0; i < 500; i = i + 1) begin
            rnd   = $random(seed);
            rnd_d = $random(seed);
            cycle(rnd[2:0] < 3'd7, rnd_d[W-1:0], rnd[5:3] < 3'd2, 1'b1);
        end
        for (i = 0; i < 500; i = i + 1) begin
            rnd   = $random(seed);
            rnd_d = $random(seed);
            cycle(rnd[2:0] < 3'd2, rnd_d[W-1:0], rnd[5:3] < 3'd7, 1'b1);
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b0, ZERO, 1'b1, 1'b1);
        end
        #1;
        chk((cnt == 2'd0) && (m_valid === 1'b0) && (s_ready === 1'b1), "random: drained");

        // G. Reset with two beats held, during traffic.
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b1, 1'b0);
        #1;
        chk((m_valid === 1'b0) && (s_ready === 1'b1), "reset: two held dropped");
        // Traffic, then reset with one beat held, lasting two cycles.
        for (i = 0; i < 20; i = i + 1) begin
            rnd = $random(seed);
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], rnd[0], 1'b1);
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b0, ZERO, 1'b1, 1'b1);
        end
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b1);
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b0, 1'b0);
        ctr = ctr + 32'd1;
        cycle(1'b1, ctr[W-1:0], 1'b1, 1'b0);
        #1;
        chk((m_valid === 1'b0) && (s_ready === 1'b1), "reset: one held dropped");
        for (i = 0; i < 20; i = i + 1) begin
            ctr = ctr + 32'd1;
            cycle(1'b1, ctr[W-1:0], 1'b1, 1'b1);
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b0, ZERO, 1'b1, 1'b1);
        end
        #1;
        chk((cnt == 2'd0) && (m_valid === 1'b0) && (s_ready === 1'b1), "after reset: drained");

        // H. Scoreboard and coverage goals.
        chk(n_in == (n_out + n_drop), "scoreboard: in = out + drop");
        chk(n_in != 32'd0, "scoreboard: beats moved");
        chk(ev_load != 32'd0, "cover: load into empty");
        chk(ev_both != 32'd0, "cover: in and out together");
        chk(ev_skid != 32'd0, "cover: accept while stalled");
        chk(ev_refuse != 32'd0, "cover: refuse when full");
        chk(ev_unstall_full != 32'd0, "cover: leave from full");
        chk(ev_hold != 32'd0, "cover: hold checked");
        chk(ev_rst_held != 32'd0, "cover: reset with beats");
        chk(ev_wiggle != 32'd0, "cover: in-cycle ready check");

        done = 1'b1;
    end
endmodule

module skid_buffer_tb;
    reg clk;
    initial clk = 1'b0;
    always #5 clk = ~clk;

    wire [31:0] p8;
    wire [31:0] f8;
    wire        d8;
    wire [31:0] p1;
    wire [31:0] f1;
    wire        d1;

    skid_buffer_tb_lane #(.W(8), .SEED(4660)) lane8 (
        .clk    (clk),
        .passed (p8),
        .failed (f8),
        .done   (d8)
    );

    skid_buffer_tb_lane #(.W(1), .SEED(22136)) lane1 (
        .clk    (clk),
        .passed (p1),
        .failed (f1),
        .done   (d1)
    );

    reg [8*64-1:0] nonce;
    reg [31:0]     passed;
    reg [31:0]     failed;
    reg [31:0]     cycles;
    integer        got;

    initial begin
        nonce  = {64{8'h00}};
        got    = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got == 0) begin
            $display("skid_buffer_tb: no nirmaan_nonce plusarg given");
        end
        cycles = 32'd0;
        @(posedge clk);
        while (!((d8 === 1'b1) && (d1 === 1'b1)) && (cycles < 32'd100000)) begin
            @(posedge clk);
            cycles = cycles + 32'd1;
        end
        #2;
        passed = p8 + p1;
        failed = f8 + f1;
        if (!((d8 === 1'b1) && (d1 === 1'b1))) begin
            failed = failed + 32'd1;
            $error("skid_buffer_tb: timeout after %0d cycles", cycles);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
